window.CIVIL_SET_DATA["past-17"] = {"title":"Past Paper Set 17","negativeMarking":0,"chapters":[{"name":"Basic Civil Engineering","questions":[{"id":"PAST-17-002","src":"PAST-17-002","text":"The section modulus of a circle is","options":[{"key":"a","text":"\\(Z = \\dfrac{\\pi d^4}{64}\\)"},{"key":"b","text":"\\(Z = \\dfrac{\\pi d^3}{128}\\)"},{"key":"c","text":"\\(Z = \\dfrac{\\pi d^3}{32}\\)"},{"key":"d","text":"\\(Z = \\dfrac{\\pi d^4}{128}\\)"}],"answer":"c","explanation":"The section modulus is \\[Z = \\dfrac{I}{y_{max}} = \\dfrac{\\pi d^4{/}64}{d{/}2} = \\dfrac{\\pi d^3}{32}\\]","marks":1,"source":{"kind":"past","set":17,"question":2,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q2 · 1 mark"},"topic":"ACiE0104"},{"id":"PAST-17-003","src":"PAST-17-003","text":"The moment of inertia of a rectangle with respect to its width (centroidal axis parallel to the width) is","options":[{"key":"a","text":"\\(\\dfrac{bd^3}{12}\\)"},{"key":"b","text":"\\(\\dfrac{bd^3}{36}\\)"},{"key":"c","text":"\\(\\dfrac{db^3}{12}\\)"},{"key":"d","text":"\\(\\dfrac{db^3}{36}\\)"}],"answer":"a","explanation":"About the centroidal axis parallel to the width \\(b\\), \\[I = \\dfrac{bd^3}{12}\\] The forms divided by 36 belong to triangles.","marks":1,"source":{"kind":"past","set":17,"question":3,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q3 · 1 mark"},"topic":"ACiE0104"},{"id":"PAST-17-018","src":"PAST-17-018","text":"The number of machine made bricks for 1 m<sup>3</sup> is","options":[{"key":"a","text":"450 Nos."},{"key":"b","text":"550 Nos."},{"key":"c","text":"500 Nos."},{"key":"d","text":"575 Nos."}],"answer":"b","explanation":"The key takes about 550 machine-made bricks per m<sup>3</sup> of brickwork, including mortar joints. The exact number depends on the brick size.","marks":1,"source":{"kind":"past","set":17,"question":18,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q18 · 1 mark"},"topic":"ACiE0106"},{"id":"PAST-17-054","src":"PAST-17-054","text":"With a percentage increase of carbon in steel, it decreases its","options":[{"key":"a","text":"strength"},{"key":"b","text":"hardness"},{"key":"c","text":"ductility"},{"key":"d","text":"brittleness"}],"answer":"c","explanation":"More carbon raises strength, hardness and brittleness but lowers ductility and weldability.","marks":1,"source":{"kind":"past","set":17,"question":54,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q54 · 1 mark"},"topic":"ACiE0101"}]},{"name":"Soil Mechanics and Foundation Engineering","questions":[{"id":"PAST-17-004","src":"PAST-17-004","text":"The vane shear test is done in","options":[{"key":"a","text":"Soft clays"},{"key":"b","text":"Coarse sand"},{"key":"c","text":"Shingle"},{"key":"d","text":"Gravel"}],"answer":"a","explanation":"The vane test measures the in-situ undrained strength and sensitivity of soft, saturated clays that are hard to sample.","marks":1,"source":{"kind":"past","set":17,"question":4,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q4 · 1 mark"},"topic":"ACiE0204"},{"id":"PAST-17-021","src":"PAST-17-021","text":"Which of the following is categorized as a deep foundation?","options":[{"key":"a","text":"Mat foundation"},{"key":"b","text":"Strap footing"},{"key":"c","text":"Spread footing"},{"key":"d","text":"Pile foundation"}],"answer":"d","explanation":"Piles transfer load to deep strata, so they are deep foundations. Mats, strap footings and spread footings are shallow.","marks":1,"source":{"kind":"past","set":17,"question":21,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q21 · 1 mark"},"topic":"ACiE0205"},{"id":"PAST-17-022","src":"PAST-17-022","text":"The exact use of the core cutter method is","options":[{"key":"a","text":"in-situ dry density of soil, specifically in fine-grained cohesive soils without stones"},{"key":"b","text":"dry density of cohesionless soil"},{"key":"c","text":"both (a) and (b)"},{"key":"d","text":"none"}],"answer":"a","explanation":"The core cutter is driven into soft, fine-grained soil free of stones to find its in-situ density. Sand replacement is used for gravelly or cohesionless soils.","marks":1,"source":{"kind":"past","set":17,"question":22,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q22 · 1 mark"},"topic":"ACiE0201"},{"id":"PAST-17-023","src":"PAST-17-023","text":"The observed N-value of an SPT test is 21. The corrected value after the dilatancy correction is","options":[{"key":"a","text":"18"},{"key":"b","text":"21"},{"key":"c","text":"19"},{"key":"d","text":"15"}],"answer":"a","explanation":"For fine or silty sand below the water table with \\(N \\gt 15\\), \\[\\begin{aligned} N' &amp;= 15 + \\dfrac{N - 15}{2} \\\\ &amp;= 15 + 3 = 18 \\end{aligned}\\]","marks":1,"source":{"kind":"past","set":17,"question":23,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q23 · 1 mark"},"topic":"ACiE0204"},{"id":"PAST-17-065","src":"PAST-17-065","text":"A soil has a porosity of 30%. Its void ratios in the loosest and densest states are 0.92 and 0.35 respectively. What will be its density index?","options":[{"key":"a","text":"0.865"},{"key":"b","text":"0.861"},{"key":"c","text":"0.872"},{"key":"d","text":"0.881"}],"answer":"b","explanation":"Here \\(e = \\dfrac{0.3}{0.7} = 0.429\\), so \\[\\begin{aligned} I_D &amp;= \\dfrac{0.92 - 0.429}{0.92 - 0.35} \\\\ &amp;\\approx 0.861 \\end{aligned}\\] (The paper lists the two void ratios the other way round.)","marks":2,"source":{"kind":"past","set":17,"question":65,"marks":2,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q65 · 2 marks"},"topic":"ACiE0201"},{"id":"PAST-17-079","src":"PAST-17-079","text":"If the bearing stress is 180 kN/m<sup>2</sup>, unit weight = 20 kN/m<sup>3</sup> and internal angle of friction = 30 degree, then according to Rankine's theory what is the minimum depth of foundation?","options":[{"key":"a","text":"0.5 m"},{"key":"b","text":"0.8 m"},{"key":"c","text":"2 m"},{"key":"d","text":"1 m"}],"answer":"d","explanation":"Rankine's minimum depth is \\[D_{min} = \\dfrac{q}{\\gamma}\\left(\\dfrac{1 - \\sin\\phi}{1 + \\sin\\phi}\\right)^2\\] \\[= 9 \\times \\left(\\dfrac{1}{3}\\right)^2 = 1\\ \\text{m}\\]","marks":2,"source":{"kind":"past","set":17,"question":79,"marks":2,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q79 · 2 marks"},"topic":"ACiE0205"}]},{"name":"Basic Water Resources Engineering","questions":[{"id":"PAST-17-048","src":"PAST-17-048","text":"What is the unit of kinematic viscosity?","options":[{"key":"a","text":"m<sup>2</sup>/s"},{"key":"b","text":"stokes"},{"key":"c","text":"Ns/m<sup>2</sup>"},{"key":"d","text":"both (a) and (b)"}],"answer":"d","explanation":"Kinematic viscosity \\(\\nu = \\dfrac{\\mu}{\\rho}\\) is measured in m<sup>2</sup> per s (SI) or stokes (cm<sup>2</sup> per s). N s per m<sup>2</sup> is the unit of dynamic viscosity. (The paper prints (a) with the exponent on the second, a misprint for m<sup>2</sup> per s.)","marks":1,"source":{"kind":"past","set":17,"question":48,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q48 · 1 mark"},"topic":"ACiE0301"},{"id":"PAST-17-049","src":"PAST-17-049","text":"A Bourdon gauge measures","options":[{"key":"a","text":"gauge pressure"},{"key":"b","text":"atmospheric pressure"},{"key":"c","text":"absolute pressure"},{"key":"d","text":"vacuum pressure"}],"answer":"a","explanation":"A Bourdon gauge reads the pressure relative to the surrounding atmosphere, i.e. gauge pressure.","marks":1,"source":{"kind":"past","set":17,"question":49,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q49 · 1 mark"},"topic":"ACiE0302"},{"id":"PAST-17-067","src":"PAST-17-067","text":"If the velocity of flow is 2.5 m/s, the depth of a trapezoidal section is 2 m, the base width is 3 m, the side slope is 1H:2V and the bed slope is 1 in 1000, what will be Manning's coefficient?","options":[{"key":"a","text":"\\(n = 0.012\\)"},{"key":"b","text":"\\(n = 0.013\\)"},{"key":"c","text":"\\(n = 0.014\\)"},{"key":"d","text":"\\(n = 0.015\\)"}],"answer":"b","explanation":"With \\(z = 0.5\\), \\[A = (3 + 0.5 \\times 2) \\times 2 = 8\\ \\text{m}^2\\] \\[\\begin{aligned} P &amp;= 3 + 2 \\times 2 \\times \\sqrt{1.25} \\\\ &amp;= 7.47\\ \\text{m} \\end{aligned}\\] so \\(R = 1.07\\) m and \\[\\begin{aligned} n &amp;= \\dfrac{R^{2{/}3}S^{1{/}2}}{V} \\\\ &amp;= \\dfrac{1.047 \\times 0.0316}{2.5} \\approx 0.013 \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":17,"question":67,"marks":2,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q67 · 2 marks"},"topic":"ACiE0305"},{"id":"PAST-17-072","src":"PAST-17-072","text":"The velocity distribution for the flow over a flat plate is given by \\(u = 2y - y^2\\), in which \\(u\\) is the velocity in m/s at a distance \\(y\\) metres above the plate. Determine the shear stress at \\(y = 0.15\\) m. Take the dynamic viscosity of the fluid as 8.5 poise.","options":[{"key":"a","text":"1.455 N/m<sup>2</sup>"},{"key":"b","text":"1.545 N/m<sup>2</sup>"},{"key":"c","text":"1.445 N/m<sup>2</sup>"},{"key":"d","text":"1.554 N/m<sup>2</sup>"}],"answer":"c","explanation":"At \\(y = 0.15\\) m the velocity gradient is \\[\\dfrac{du}{dy} = 2 - 2y = 1.7\\ \\text{s}^{-1}\\] With \\(\\mu = 0.85\\) Pa s, \\[\\begin{aligned} \\tau &amp;= \\mu\\dfrac{du}{dy} = 0.85 \\times 1.7 \\\\ &amp;= 1.445 \\end{aligned}\\] N per m<sup>2</sup>.","marks":2,"source":{"kind":"past","set":17,"question":72,"marks":2,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q72 · 2 marks"},"topic":"ACiE0301"},{"id":"PAST-17-075","src":"PAST-17-075","text":"The sequent depth ratio of a hydraulic jump in a rectangular channel is 16.48. What is the Froude number (approximately) at the beginning of the jump?","options":[{"key":"a","text":"5"},{"key":"b","text":"9"},{"key":"c","text":"8"},{"key":"d","text":"12"}],"answer":"d","explanation":"From \\[\\dfrac{1}{2}\\left[\\sqrt{1 + 8F^2} - 1\\right] = 16.48\\] \\(\\sqrt{1 + 8F^2} = 33.96\\), so \\(F \\approx 12\\).","marks":2,"source":{"kind":"past","set":17,"question":75,"marks":2,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q75 · 2 marks"},"topic":"ACiE0305"},{"id":"PAST-17-076","src":"PAST-17-076","text":"Calculate the wetted perimeter for a trapezoidal section if \\(z\\), \\(y\\) and \\(B\\) are given.","options":[{"key":"a","text":"\\(B - 2y\\sqrt{1+z^2}\\)"},{"key":"b","text":"\\(B + 2y\\sqrt{1+z^2}\\)"},{"key":"c","text":"\\(B + y\\sqrt{1+z^2}\\)"},{"key":"d","text":"None of these"}],"answer":"b","explanation":"The wetted perimeter is the bed plus two sloping sides: \\[P = B + 2y\\sqrt{1 + z^2}\\] (The paper repeats option (a) as (d); it is shown here as 'None of these'.)","marks":2,"source":{"kind":"past","set":17,"question":76,"marks":2,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q76 · 2 marks"},"topic":"ACiE0305"}]},{"name":"Structural Mechanics","questions":[{"id":"PAST-17-007","src":"PAST-17-007","text":"The kinematic indeterminacy of a propped cantilever beam with axial deformation is","options":[{"key":"a","text":"0"},{"key":"b","text":"1"},{"key":"c","text":"2"},{"key":"d","text":"3"}],"answer":"c","explanation":"The fixed end has no free displacement. The roller end can rotate and move horizontally (axial deformation considered), giving 2 degrees of freedom.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-17-007-propped-cantilever-degrees-of-freedom.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Free joint displacements of a propped cantilever'><img src='assets/civil-past-solutions/past-17-007-propped-cantilever-degrees-of-freedom.svg' width='720' height='420' loading='lazy' decoding='async' alt='The fixed end A cannot move or rotate. The roller at B stops vertical movement but leaves the rotation θB and, when axial deformation is counted, the horizontal movement uB free, so the kinematic indeterminacy is 2.'></a><figcaption>Free joint displacements of a propped cantilever</figcaption></figure>","marks":1,"source":{"kind":"past","set":17,"question":7,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q7 · 1 mark"},"topic":"ACiE0406"},{"id":"PAST-17-016","src":"PAST-17-016","text":"The ILD for the shear force at the support of a cantilever beam is a","options":[{"key":"a","text":"triangle"},{"key":"b","text":"rectangle"},{"key":"c","text":"cubic parabola"},{"key":"d","text":"square parabola"}],"answer":"b","explanation":"Wherever the unit load stands on the cantilever, the support shear (reaction) is 1, so the ILD is a rectangle of unit height.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-11-039-cantilever-support-influence-line.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Influence line for the reaction and shear at a cantilever support'><img src='assets/civil-past-solutions/past-11-039-cantilever-support-influence-line.svg' width='720' height='420' loading='lazy' decoding='async' alt='Wherever the unit load stands on a cantilever, the whole of it goes to the fixed support, so the reaction and the support shear are always 1. The influence line is a rectangle of unit height over the length.'></a><figcaption>Influence line for the reaction and shear at a cantilever support</figcaption></figure>","marks":1,"source":{"kind":"past","set":17,"question":16,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q16 · 1 mark"},"topic":"ACiE0404"},{"id":"PAST-17-024","src":"PAST-17-024","text":"The formula to get the horizontal reaction in a two hinged arch is","options":[{"key":"a","text":"\\(\\dfrac{\\int My\\,ds/EI}{\\int y^2\\,ds/EI}\\)"},{"key":"b","text":"\\(\\dfrac{wl^2}{64}\\)"},{"key":"c","text":"\\(\\dfrac{5wl^2}{96}\\)"},{"key":"d","text":"None"}],"answer":"a","explanation":"Castigliano's theorem, with zero relative spread of the hinges, gives \\[H = \\dfrac{\\displaystyle\\int \\dfrac{My\\,ds}{EI}}{\\displaystyle\\int \\dfrac{y^2\\,ds}{EI}}\\]<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-05-028-thrust-from-the-released-arch.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Horizontal thrust of a two-hinged arch from the released structure'><img src='assets/civil-past-solutions/past-05-028-thrust-from-the-released-arch.svg' width='720' height='420' loading='lazy' decoding='async' alt='Releasing the horizontal restraint at B turns the arch into a curved beam whose supports spread by the integral of My ds/EI, where M is the free-beam moment and y the height of the element ds. H must close this gap, and it moves B back by H times the integral of y squared ds/EI.'></a><figcaption>Horizontal thrust of a two-hinged arch from the released structure</figcaption></figure>","marks":1,"source":{"kind":"past","set":17,"question":24,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q24 · 1 mark"},"topic":"ACiE0406"},{"id":"PAST-17-050","src":"PAST-17-050","text":"The stiffness of a member if the farther end is hinged is","options":[{"key":"a","text":"\\(0\\)"},{"key":"b","text":"\\(\\dfrac{EI}{L}\\)"},{"key":"c","text":"\\(\\dfrac{3EI}{L}\\)"},{"key":"d","text":"\\(\\dfrac{4EI}{L}\\)"}],"answer":"c","explanation":"With the far end pinned, a unit near-end rotation needs 3EI/L.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-16-075-stiffness-far-end-hinged.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Moment needed to rotate the near end with the far end hinged'><img src='assets/civil-past-solutions/past-16-075-stiffness-far-end-hinged.svg' width='720' height='420' loading='lazy' decoding='async' alt='With the far end B pinned it can rotate freely, so no moment is carried over and the member is more flexible. A unit rotation at A needs 3EI/L instead of the 4EI/L needed when B is fixed.'></a><figcaption>Moment needed to rotate the near end with the far end hinged</figcaption></figure>","marks":1,"source":{"kind":"past","set":17,"question":50,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q50 · 1 mark"},"topic":"ACiE0406"},{"id":"PAST-17-051","src":"PAST-17-051","text":"The radial thrust (force along the radius) on a 3-hinged arch is","options":[{"key":"a","text":"\\(H\\cos\\theta + V\\sin\\theta\\)"},{"key":"b","text":"\\(H\\sin\\theta - V\\cos\\theta\\)"},{"key":"c","text":"\\(V\\cos\\theta - H\\sin\\theta\\)"},{"key":"d","text":"None"}],"answer":"c","explanation":"Resolving H and V along the radius (normal to the arch axis) gives the radial force V cosθ − H sinθ, the radial shear. The force along the axis, H cosθ + V sinθ, is the normal thrust.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-10-039-resolving-h-and-v-at-an-arch-section.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Resolving H and V at an arch section into thrust and radial shear'><img src='assets/civil-past-solutions/past-10-039-resolving-h-and-v-at-an-arch-section.svg' width='720' height='420' loading='lazy' decoding='async' alt='At a section where the arch tangent makes θ with the horizontal, the components of H and V along the tangent add to the normal thrust N = H cosθ + V sinθ, and the components along the radius give the radial shear S = V cosθ - H sinθ.'></a><figcaption>Resolving H and V at an arch section into thrust and radial shear</figcaption></figure>","marks":1,"source":{"kind":"past","set":17,"question":51,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q51 · 1 mark"},"topic":"ACiE0405"},{"id":"PAST-17-052","src":"PAST-17-052","text":"The maximum bending moment in a simply supported beam due to a train of wheel loads","options":[{"key":"a","text":"always occurs at the centre of span"},{"key":"b","text":"always occurs under a wheel load"},{"key":"c","text":"never occurs under a wheel load"},{"key":"d","text":"none of the above"}],"answer":"b","explanation":"For concentrated moving loads the moment peaks under one of the loads, placed so that the load and the resultant are equidistant from midspan.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-04-005-moment-peaks-under-a-wheel.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Under wheel loads the moment peaks beneath a wheel'><img src='assets/civil-past-solutions/past-04-005-moment-peaks-under-a-wheel.svg' width='720' height='420' loading='lazy' decoding='async' alt='For any position of a train of concentrated loads the shear is constant between the wheels, so the moment diagram is made of straight lines with its corners under the wheels. The maximum, and hence the absolute maximum, always occurs under a wheel load.'></a><figcaption>Under wheel loads the moment peaks beneath a wheel</figcaption></figure>","marks":1,"source":{"kind":"past","set":17,"question":52,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q52 · 1 mark"},"topic":"ACiE0404"},{"id":"PAST-17-053","src":"PAST-17-053","text":"The ratio of linear stress to linear strain is called","options":[{"key":"a","text":"modulus of rigidity"},{"key":"b","text":"modulus of elasticity"},{"key":"c","text":"bulk modulus"},{"key":"d","text":"Poisson's ratio"}],"answer":"b","explanation":"Young's modulus is \\[E = \\dfrac{\\text{normal stress}}{\\text{normal strain}}\\] The modulus of rigidity relates shear stress to shear strain.","marks":1,"source":{"kind":"past","set":17,"question":53,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q53 · 1 mark"},"topic":"ACiE0402"},{"id":"PAST-17-078","src":"PAST-17-078","text":"The horizontal thrust in a two hinged semi-circular arch subjected to a UDL of \\(w\\) kN/m over the left half span will be","options":[{"key":"a","text":"\\(\\dfrac{4wR}{3\\pi}\\)"},{"key":"b","text":"\\(\\dfrac{wR}{2}\\)"},{"key":"c","text":"\\(wR\\)"},{"key":"d","text":"\\(\\dfrac{2wR}{3\\pi}\\)"}],"answer":"d","explanation":"A full-span UDL gives \\[H = \\dfrac{4wR}{3\\pi}\\] so a half-span UDL gives half of that, \\(\\dfrac{2wR}{3\\pi}\\).<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-07-066-semicircular-arch-half-span-load.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Two-hinged semicircular arch loaded over the left half'><img src='assets/civil-past-solutions/past-07-066-semicircular-arch-half-span-load.svg' width='720' height='420' loading='lazy' decoding='async' alt='A uniform load w over the whole span of a two-hinged semicircular arch gives H = 4wR/3π. The thrust is linear in the load, and each half of the load contributes equally by symmetry, so loading only the left half gives H = 2wR/3π.'></a><figcaption>Two-hinged semicircular arch loaded over the left half</figcaption></figure>","marks":2,"source":{"kind":"past","set":17,"question":78,"marks":2,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q78 · 2 marks"},"topic":"ACiE0406"}]},{"name":"Design of Structures","questions":[{"id":"PAST-17-001","src":"PAST-17-001","text":"Minimum welding (weld length) in a batten","options":[{"key":"a","text":"length of weld connecting each end of batten should be less than one fourth the depth of plate"},{"key":"b","text":"length of weld and depth of batten shall be measured perpendicular to the longitudinal axis of the member"},{"key":"c","text":"length of weld connecting each end of batten should be such that at least one third of its length should be placed on each end"},{"key":"d","text":"weld shall be returned only along the other two edges for length less than minimum lap"}],"answer":"c","explanation":"Following the key's IS 800 provision, the welds connecting each end of a batten plate must total enough length, with at least one-third of it placed at each end of the batten.","marks":1,"source":{"kind":"past","set":17,"question":1,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q1 · 1 mark"},"topic":"ACiE0505"},{"id":"PAST-17-012","src":"PAST-17-012","text":"The modulus of elasticity of M25 concrete is","options":[{"key":"a","text":"33500 N/mm<sup>2</sup>"},{"key":"b","text":"18500 N/mm<sup>2</sup>"},{"key":"c","text":"25000 N/mm<sup>2</sup>"},{"key":"d","text":"28500 N/mm<sup>2</sup>"}],"answer":"c","explanation":"IS 456 gives \\[\\begin{aligned} E_c &amp;= 5000\\sqrt{f_{ck}} = 5000 \\times 5 \\\\ &amp;= 25{,}000 \\end{aligned}\\] N per mm<sup>2</sup>.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-17-012-modulus-of-m25-concrete.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Short-term modulus of elasticity of M25 concrete'><img src='assets/civil-past-solutions/past-17-012-modulus-of-m25-concrete.svg' width='720' height='420' loading='lazy' decoding='async' alt='IS 456 gives the short-term static modulus of concrete as Ec = 5000√fck, the slope of the early part of the stress-strain curve. For M25, Ec = 5000 x √25 = 5000 x 5 = 25 000 N/mm squared.'></a><figcaption>Short-term modulus of elasticity of M25 concrete</figcaption></figure>","marks":1,"source":{"kind":"past","set":17,"question":12,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q12 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-17-019","src":"PAST-17-019","text":"NBC 102 talks about","options":[{"key":"a","text":"unit weight of material"},{"key":"b","text":"imposed load"},{"key":"c","text":"snow load"},{"key":"d","text":"seismic design of buildings in Nepal"}],"answer":"a","explanation":"NBC 102 gives the unit weights of building materials for dead-load calculation. NBC 103 covers imposed loads, NBC 104 wind, NBC 105 seismic design and NBC 106 snow.","marks":1,"source":{"kind":"past","set":17,"question":19,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q19 · 1 mark"},"topic":"ACiE0501"},{"id":"PAST-17-020","src":"PAST-17-020","text":"Cyclopean aggregate has a size more than","options":[{"key":"a","text":"4.75 mm"},{"key":"b","text":"25 mm"},{"key":"c","text":"45 mm"},{"key":"d","text":"75 mm"}],"answer":"d","explanation":"Cyclopean (plum) concrete embeds very large stones, well above the normal 75 mm maximum aggregate size (often 150 mm or more), in mass concrete.","marks":1,"source":{"kind":"past","set":17,"question":20,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q20 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-17-056","src":"PAST-17-056","text":"Based on wind speed, Nepal is divided into …… zones","options":[{"key":"a","text":"1"},{"key":"b","text":"2"},{"key":"c","text":"3"},{"key":"d","text":"4"}],"answer":"b","explanation":"NBC 104 defines two wind zones: basic wind speed 47 m/s below 3000 m elevation and 55 m/s above.","marks":1,"source":{"kind":"past","set":17,"question":56,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q56 · 1 mark"},"topic":"ACiE0501"},{"id":"PAST-17-060","src":"PAST-17-060","text":"The test intended to study the resistance of aggregates to weathering action is the","options":[{"key":"a","text":"abrasion test"},{"key":"b","text":"crushing test"},{"key":"c","text":"impact test"},{"key":"d","text":"soundness test"}],"answer":"d","explanation":"The soundness test (sodium or magnesium sulphate cycles) measures resistance to weathering. The others test hardness, strength and toughness.","marks":1,"source":{"kind":"past","set":17,"question":60,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q60 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-17-068","src":"PAST-17-068","text":"As per Indian Standard (IS) 456:2000, the minimum area of tension reinforcement in a beam when Fe415 steel is used is","options":[{"key":"a","text":"0.02%"},{"key":"b","text":"0.2%"},{"key":"c","text":"0.085%"},{"key":"d","text":"0.85%"}],"answer":"b","explanation":"The minimum tension steel is \\[\\begin{aligned} \\dfrac{A_s}{bd} &amp;\\ge \\dfrac{0.85}{f_y} = \\dfrac{0.85}{415} \\\\ &amp;\\approx 0.205\\% \\end{aligned}\\] i.e. about 0.2%.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-17-068-minimum-steel-ratio-by-grade.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Minimum tension steel ratio 0.85/fy for common steel grades'><img src='assets/civil-past-solutions/past-17-068-minimum-steel-ratio-by-grade.svg' width='720' height='420' loading='lazy' decoding='async' alt='The minimum tension steel ratio of IS 456 is As/bd = 0.85/fy, so it falls as the steel grade rises. For Fe415 it is 0.85/415 = 0.00205, about 0.2 percent.'></a><figcaption>Minimum tension steel ratio 0.85/fy for common steel grades</figcaption></figure>","marks":2,"source":{"kind":"past","set":17,"question":68,"marks":2,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q68 · 2 marks"},"topic":"ACiE0503"},{"id":"PAST-17-074","src":"PAST-17-074","text":"If the basic wind speed = 55 m/s and \\(k_1\\), \\(k_2\\), \\(k_3\\) are all 1, then the wind pressure considered is","options":[{"key":"a","text":"18.15 N/m<sup>2</sup>"},{"key":"b","text":"181.5 N/m<sup>2</sup>"},{"key":"c","text":"18150 N/m<sup>2</sup>"},{"key":"d","text":"1815 N/m<sup>2</sup>"}],"answer":"d","explanation":"The design wind pressure is \\[\\begin{aligned} p_z &amp;= 0.6V_z^2 = 0.6 \\times 55^2 \\\\ &amp;= 1815 \\end{aligned}\\] N per m<sup>2</sup>.<figure class='cn-explanation-figure'><a href='assets/civil-past-solutions/past-09-080-design-wind-pressure.svg' target='_blank' rel='noopener noreferrer' aria-label='Open Design wind pressure from a basic wind speed of 55 m/s'><img src='assets/civil-past-solutions/past-09-080-design-wind-pressure.svg' width='720' height='420' loading='lazy' decoding='async' alt='With k1 = k2 = k3 = 1 the design wind speed equals the basic speed, Vz = 55 m/s. The design wind pressure is pz = 0.6 Vz squared = 0.6 x 55 squared = 1815 N/m squared.'></a><figcaption>Design wind pressure from a basic wind speed of 55 m/s</figcaption></figure>","marks":2,"source":{"kind":"past","set":17,"question":74,"marks":2,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q74 · 2 marks"},"topic":"ACiE0501"}]},{"name":"Water Supply, Sanitation and Environment","questions":[{"id":"PAST-17-011","src":"PAST-17-011","text":"Blue baby syndrome is due to","options":[{"key":"a","text":"Nitrate"},{"key":"b","text":"Carbon dioxide"},{"key":"c","text":"Iron"},{"key":"d","text":"Carbon monoxide"}],"answer":"a","explanation":"Excess nitrate in drinking water causes methaemoglobinaemia (blue baby syndrome) in infants.","marks":1,"source":{"kind":"past","set":17,"question":11,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q11 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-17-015","src":"PAST-17-015","text":"A disease spread worldwide is called","options":[{"key":"a","text":"Endemic"},{"key":"b","text":"Epidemic"},{"key":"c","text":"Pandemic"},{"key":"d","text":"All of the above"}],"answer":"c","explanation":"A pandemic is an epidemic that spreads across countries and continents.","marks":1,"source":{"kind":"past","set":17,"question":15,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q15 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-17-038","src":"PAST-17-038","text":"If the discharge is 0.16 cumecs, the economic diameter will be","options":[{"key":"a","text":"0.488 m"},{"key":"b","text":"0.513 m"},{"key":"c","text":"0.546 m"},{"key":"d","text":"0.588 m"}],"answer":"a","explanation":"Lea's formula gives \\[\\begin{aligned} D &amp;= 1.22\\sqrt{Q} = 1.22 \\times 0.4 \\\\ &amp;= 0.488\\ \\text{m} \\end{aligned}\\]","marks":1,"source":{"kind":"past","set":17,"question":38,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q38 · 1 mark"},"topic":"ACiE0602"},{"id":"PAST-17-043","src":"PAST-17-043","text":"The function of a reflux valve is","options":[{"key":"a","text":"to prevent back flow"},{"key":"b","text":"to release high pressure"},{"key":"c","text":"to wash out the sewerage pipe"},{"key":"d","text":"all of the above"}],"answer":"a","explanation":"A reflux (non-return or check) valve lets flow pass in one direction only and closes against reverse flow, for example at pump outlets and outfalls.","marks":1,"source":{"kind":"past","set":17,"question":43,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q43 · 1 mark"},"topic":"ACiE0604"},{"id":"PAST-17-044","src":"PAST-17-044","text":"An inverted syphon is also called a","options":[{"key":"a","text":"lateral sewer"},{"key":"b","text":"outfall sewer"},{"key":"c","text":"depressed sewer"},{"key":"d","text":"main sewer"}],"answer":"c","explanation":"An inverted siphon (depressed sewer) dips below an obstruction and runs full under pressure.","marks":1,"source":{"kind":"past","set":17,"question":44,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q44 · 1 mark"},"topic":"ACiE0604"},{"id":"PAST-17-045","src":"PAST-17-045","text":"The filtration rate of a rapid sand filter is","options":[{"key":"a","text":"2000-3000 litres per hour per sq. m"},{"key":"b","text":"3000-6000 litres per hour per sq. m"},{"key":"c","text":"6000-8000 litres per hour per sq. m"},{"key":"d","text":"100-200 litres per hour per sq. m"}],"answer":"b","explanation":"Rapid sand filters work at 3000-6000 litres per hour per m<sup>2</sup>. Slow sand filters work at 100-200 litres per hour per m<sup>2</sup>.","marks":1,"source":{"kind":"past","set":17,"question":45,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q45 · 1 mark"},"topic":"ACiE0603"},{"id":"PAST-17-046","src":"PAST-17-046","text":"The full form of BES is","options":[{"key":"a","text":"Bachelor of Electronic Science"},{"key":"b","text":"Bachelors in Engineering Science"},{"key":"c","text":"Bachelors in Environmental Science"},{"key":"d","text":"Brief Environmental Study"}],"answer":"d","explanation":"BES is the Brief Environmental Study, the lightest level of environmental assessment under Nepal's Environment Protection Rules 2077.","marks":1,"source":{"kind":"past","set":17,"question":46,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q46 · 1 mark"},"topic":"ACiE0606"},{"id":"PAST-17-047","src":"PAST-17-047","text":"The permanent hardness of water is removed by","options":[{"key":"a","text":"lime soda method"},{"key":"b","text":"ion exchange process"},{"key":"c","text":"boiling"},{"key":"d","text":"(a) and (b)"}],"answer":"d","explanation":"Permanent (sulphate and chloride) hardness is not removed by boiling. It needs lime-soda softening or ion exchange (zeolite or resins).","marks":1,"source":{"kind":"past","set":17,"question":47,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q47 · 1 mark"},"topic":"ACiE0603"},{"id":"PAST-17-062","src":"PAST-17-062","text":"A (combined) sewerage system is designed with","options":[{"key":"a","text":"peak factor × dry weather flow"},{"key":"b","text":"peak factor × water supply"},{"key":"c","text":"return factor × population × rate of water supply × peak factor"},{"key":"d","text":"DWF + WWF"}],"answer":"d","explanation":"A combined system carries both sewage and storm water, so its design flow is dry-weather flow plus wet-weather (storm) flow. Options (a) and (c) express the same peak sanitary flow for separate sewers.","marks":2,"source":{"kind":"past","set":17,"question":62,"marks":2,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q62 · 2 marks"},"topic":"ACiE0604"},{"id":"PAST-17-080","src":"PAST-17-080","text":"If the initial population of a country is 1000000 and the birth rate and death rate are 10% and 4% respectively, what is the population of the country after 2 years?","options":[{"key":"a","text":"1126000"},{"key":"b","text":"1023600"},{"key":"c","text":"1123000"},{"key":"d","text":"1123600"}],"answer":"d","explanation":"The net growth rate is \\(10 - 4 = 6\\%\\) a year, compounded: \\[\\begin{aligned} P &amp;= 1{,}000{,}000 \\times 1.06^2 \\\\ &amp;= 1{,}123{,}600 \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":17,"question":80,"marks":2,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q80 · 2 marks"},"topic":"ACiE0601"}]},{"name":"Irrigation and Drainage","questions":[{"id":"PAST-17-008","src":"PAST-17-008","text":"The length of an upstream guide bank is","options":[{"key":"a","text":"1.25L"},{"key":"b","text":"1.75L"},{"key":"c","text":"2.25L"},{"key":"d","text":"0.4L"}],"answer":"a","explanation":"Upstream guide banks are typically 1.0–1.5L long (commonly 1.25L), and downstream ones 0.2–0.4L, where L is the waterway length.","marks":1,"source":{"kind":"past","set":17,"question":8,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q8 · 1 mark"},"topic":"ACiE0704"},{"id":"PAST-17-014","src":"PAST-17-014","text":"The main difference between a weir and a dam is","options":[{"key":"a","text":"a dam stops the flow of water, while a weir allows water to flow over its crest"},{"key":"b","text":"a dam has more storage capacity as compared to a weir"},{"key":"c","text":"the height of a dam is more than that of a weir"},{"key":"d","text":"all of the above"}],"answer":"d","explanation":"A weir is a low barrier over which water flows, raising the level only slightly and storing little. A dam is higher, stores water behind it and passes floods only through spillways. All three statements are true.","marks":1,"source":{"kind":"past","set":17,"question":14,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q14 · 1 mark"},"topic":"ACiE0703"},{"id":"PAST-17-017","src":"PAST-17-017","text":"A hydraulic structure constructed when the full supply level (FSL) of a canal is much higher than the high flood level (HFL) of the stream, which in turn is lower than the bottom of the canal trough, is called a","options":[{"key":"a","text":"super passage"},{"key":"b","text":"aqueduct"},{"key":"c","text":"inlet"},{"key":"d","text":"level crossing"}],"answer":"b","explanation":"When the canal bed is above the drain's HFL, the canal is carried over the drain in a trough and the drain flows freely below. This is an aqueduct.","marks":1,"source":{"kind":"past","set":17,"question":17,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q17 · 1 mark"},"topic":"ACiE0705"},{"id":"PAST-17-037","src":"PAST-17-037","text":"If the length of the barrage is 400 m, the lengths of the upstream and downstream guide banks are","options":[{"key":"a","text":"u/s = 500 m, d/s = 200 m"},{"key":"b","text":"u/s = 600 m, d/s = 100 m"},{"key":"c","text":"u/s = 400 m, d/s = 70 m"},{"key":"d","text":"u/s = 500 m, d/s = 100 m"}],"answer":"d","explanation":"Taking about 1.25L upstream and 0.25L downstream gives 500 m and 100 m.","marks":1,"source":{"kind":"past","set":17,"question":37,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q37 · 1 mark"},"topic":"ACiE0704"},{"id":"PAST-17-039","src":"PAST-17-039","text":"The crop which can withstand the maximum water table is","options":[{"key":"a","text":"Rice"},{"key":"b","text":"Wheat"},{"key":"c","text":"Millet"},{"key":"d","text":"Corn"}],"answer":"a","explanation":"Paddy grows in standing water and tolerates a very high water table, whereas wheat, maize and millets need well-drained root zones.","marks":1,"source":{"kind":"past","set":17,"question":39,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q39 · 1 mark"},"topic":"ACiE0701"},{"id":"PAST-17-040","src":"PAST-17-040","text":"Calculate Lacey's silt factor for a diameter of 0.5 mm.","options":[{"key":"a","text":"1.545"},{"key":"b","text":"1.445"},{"key":"c","text":"1.245"},{"key":"d","text":"1.221"}],"answer":"c","explanation":"Lacey's silt factor is \\[f = 1.76\\sqrt{0.5} \\approx 1.245\\]","marks":1,"source":{"kind":"past","set":17,"question":40,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q40 · 1 mark"},"topic":"ACiE0702"},{"id":"PAST-17-042","src":"PAST-17-042","text":"The formula to calculate the tractive force at the bottom of a channel is","options":[{"key":"a","text":"\\(\\tau_0 = 2\\gamma RS_0\\)"},{"key":"b","text":"\\(\\tau_0 = 0.78\\gamma yS_0\\)"},{"key":"c","text":"\\(\\tau_0 = \\gamma RS_0\\)"},{"key":"d","text":"None of the above"}],"answer":"c","explanation":"The average boundary shear (tractive force) is \\[\\tau_0 = \\gamma RS_0\\] and it tends to \\(\\gamma yS_0\\) for wide channels. The maximum on the sides is about \\(0.76\\) to \\(0.78\\gamma yS_0\\).","marks":1,"source":{"kind":"past","set":17,"question":42,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q42 · 1 mark"},"topic":"ACiE0702"},{"id":"PAST-17-057","src":"PAST-17-057","text":"Nappe means","options":[{"key":"a","text":"flowing water above the crest"},{"key":"b","text":"flowing water below the crest"},{"key":"c","text":"water stored behind the weir"},{"key":"d","text":"none"}],"answer":"a","explanation":"The nappe is the sheet of water flowing over the crest of a weir or notch.","marks":1,"source":{"kind":"past","set":17,"question":57,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q57 · 1 mark"},"topic":"ACiE0703"},{"id":"PAST-17-061","src":"PAST-17-061","text":"Find the delta for a crop if the duty for a base period of 120 days is 1500 hectares/cumec.","options":[{"key":"a","text":"692 mm"},{"key":"b","text":"691 mm"},{"key":"c","text":"690 mm"},{"key":"d","text":"689 mm"}],"answer":"b","explanation":"The delta is \\[\\begin{aligned} \\Delta &amp;= \\dfrac{8.64B}{D} = \\dfrac{8.64 \\times 120}{1500} \\\\ &amp;= 0.691 \\end{aligned}\\] metres, about 691 mm.","marks":2,"source":{"kind":"past","set":17,"question":61,"marks":2,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q61 · 2 marks"},"topic":"ACiE0701"},{"id":"PAST-17-073","src":"PAST-17-073","text":"A launching apron is to be designed downstream of a weir for a discharge intensity of 6.5 m<sup>3</sup>/s/m. For the design of launching aprons, the scour depth is taken as two times the Lacey scour depth. The silt factor of the bed material is unity. If the tailwater depth is 4.4 m, the length of the launching apron in the launched position is","options":[{"key":"a","text":"2.5 m"},{"key":"b","text":"4.5 m"},{"key":"c","text":"5 m"},{"key":"d","text":"6 m"}],"answer":"c","explanation":"Lacey's scour depth is \\[\\begin{aligned} R &amp;= 1.35\\left(\\dfrac{6.5^2}{1}\\right)^{1{/}3} \\\\ &amp;\\approx 4.70\\ \\text{m} \\end{aligned}\\] The design scour level lies \\[2 \\times 4.70 - 4.4 \\approx 5.0\\ \\text{m}\\] below the bed, and the key takes this 5 m as the answer. Laid at 2:1, the sloping launched length would be about \\(\\sqrt{5} \\times 5 \\approx 11\\) m.","marks":2,"source":{"kind":"past","set":17,"question":73,"marks":2,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q73 · 2 marks"},"topic":"ACiE0704"}]},{"name":"Hydropower","questions":[{"id":"PAST-17-036","src":"PAST-17-036","text":"Which is the formula for the plant (capacity) factor?","options":[{"key":"a","text":"Plant or capacity factor = average load / peak load"},{"key":"b","text":"Plant or capacity factor = peak load / installed capacity"},{"key":"c","text":"Plant or capacity factor = average load / plant capacity"},{"key":"d","text":"Plant or capacity factor = actual power / apparent power"}],"answer":"c","explanation":"The capacity factor is the average load divided by the installed plant capacity. Average over peak is the load factor, and actual over apparent power is the power factor.","marks":1,"source":{"kind":"past","set":17,"question":36,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q36 · 1 mark"},"topic":"ACiE0802"},{"id":"PAST-17-041","src":"PAST-17-041","text":"Which of the following is the function of a surge tank?","options":[{"key":"a","text":"Absorb sudden rises of pressure in a closed aqueduct, feeder pipe or dam"},{"key":"b","text":"Provide extra water during a brief drop in pressure"},{"key":"c","text":"Protect the conduit system from high internal pressures by acting as a buffer"},{"key":"d","text":"All of the above"}],"answer":"d","explanation":"A surge tank takes in water when gates close suddenly (absorbing the pressure rise) and supplies water when demand rises, buffering the conduit against water hammer.","marks":1,"source":{"kind":"past","set":17,"question":41,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q41 · 1 mark"},"topic":"ACiE0805"},{"id":"PAST-17-058","src":"PAST-17-058","text":"A Kaplan turbine is a","options":[{"key":"a","text":"reaction turbine"},{"key":"b","text":"impulse turbine"},{"key":"c","text":"Turgo turbine"},{"key":"d","text":"mechanical turbine"}],"answer":"a","explanation":"The Kaplan is an axial-flow reaction turbine with adjustable blades, used for low heads and large flows.","marks":1,"source":{"kind":"past","set":17,"question":58,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q58 · 1 mark"},"topic":"ACiE0806"},{"id":"PAST-17-064","src":"PAST-17-064","text":"Calculate the capacity factor if the average load is 36,000 kW with two turbo generators installed, each of capacity 20,000 kW.","options":[{"key":"a","text":"70%"},{"key":"b","text":"90%"},{"key":"c","text":"95%"},{"key":"d","text":"60%"}],"answer":"b","explanation":"The capacity factor is the average load divided by the installed capacity: \\[\\dfrac{36{,}000}{40{,}000} = 90\\%\\]","marks":2,"source":{"kind":"past","set":17,"question":64,"marks":2,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q64 · 2 marks"},"topic":"ACiE0802"},{"id":"PAST-17-066","src":"PAST-17-066","text":"The thickness of a penstock pipe is given by the ASME recommendation as","options":[{"key":"a","text":"\\(t_\\mathrm{cm} = \\dfrac{P + R}{\\sigma\\eta - 0.6P}\\) \\(+\\,0.15\\)"},{"key":"b","text":"\\(t_\\mathrm{cm} = \\dfrac{PR}{\\sigma\\eta + 0.6P}\\) \\(+\\,0.15\\)"},{"key":"c","text":"\\(t_\\mathrm{cm} = \\dfrac{PR}{\\sigma\\eta - 0.6P}\\) \\(-\\,0.15\\)"},{"key":"d","text":"\\(t_\\mathrm{cm} = \\dfrac{PR}{\\sigma\\eta - 0.6P}\\) \\(+\\,0.15\\)"}],"answer":"d","explanation":"The ASME boiler-code form \\[t = \\dfrac{PR}{\\sigma\\eta - 0.6P} + 0.15\\] in cm includes the joint efficiency \\(\\eta\\) and a 1.5 mm corrosion allowance.","marks":2,"source":{"kind":"past","set":17,"question":66,"marks":2,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q66 · 2 marks"},"topic":"ACiE0805"},{"id":"PAST-17-069","src":"PAST-17-069","text":"Two Pelton wheel turbines X and Y have the same specific speed and are working under the same head. Turbine X produces 400 kW at 1000 rpm. If turbine Y produces 100 kW, then its rpm is","options":[{"key":"a","text":"3000"},{"key":"b","text":"1500"},{"key":"c","text":"2000"},{"key":"d","text":"4000"}],"answer":"c","explanation":"With the same \\(N_s\\) and \\(H\\), \\(N\\sqrt{P}\\) is constant: \\[\\begin{aligned} N_Y &amp;= 1000 \\times \\sqrt{\\dfrac{400}{100}} \\\\ &amp;= 2000\\ \\text{rpm} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":17,"question":69,"marks":2,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q69 · 2 marks"},"topic":"ACiE0806"},{"id":"PAST-17-077","src":"PAST-17-077","text":"If the total hydroelectric potential of a plant is 84 GW, convert the potential into energy considering a load factor of 60%.","options":[{"key":"a","text":"441 TWh"},{"key":"b","text":"735 TWh"},{"key":"c","text":"1226 TWh"},{"key":"d","text":"504 TWh"}],"answer":"a","explanation":"The annual energy is \\[\\begin{aligned} E &amp;= 84 \\times 8760 \\times 0.6 \\\\ &amp;\\approx 441{,}500\\ \\text{GWh} \\\\ &amp;\\approx 441\\ \\text{TWh} \\end{aligned}\\] with the power in GW and the year as 8760 h.","marks":2,"source":{"kind":"past","set":17,"question":77,"marks":2,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q77 · 2 marks"},"topic":"ACiE0802"}]},{"name":"Transportation","questions":[{"id":"PAST-17-013","src":"PAST-17-013","text":"What is the standard temperature for the Marshall stability test?","options":[{"key":"a","text":"27°C"},{"key":"b","text":"60°C"},{"key":"c","text":"25°C"},{"key":"d","text":"40°C"}],"answer":"b","explanation":"Marshall specimens are tested at 60°C after conditioning in a water bath.","marks":1,"source":{"kind":"past","set":17,"question":13,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q13 · 1 mark"},"topic":"ACiE0903"},{"id":"PAST-17-030","src":"PAST-17-030","text":"The minimum (design) value of the coefficient of lateral friction is","options":[{"key":"a","text":"0.13"},{"key":"b","text":"0.15"},{"key":"c","text":"0.17"},{"key":"d","text":"0.2"}],"answer":"b","explanation":"Highway curve design adopts a lateral friction coefficient of 0.15.","marks":1,"source":{"kind":"past","set":17,"question":30,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q30 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-17-031","src":"PAST-17-031","text":"The width of a single lane road is","options":[{"key":"a","text":"3.5 m"},{"key":"b","text":"3.75 m"},{"key":"c","text":"3.0 m"},{"key":"d","text":"5.5 m"}],"answer":"b","explanation":"A single-lane carriageway is 3.75 m wide under IRC and the Nepal Road Standard. Multi-lane roads use 3.5 m per lane.","marks":1,"source":{"kind":"past","set":17,"question":31,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q31 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-17-032","src":"PAST-17-032","text":"The formula for super elevation is","options":[{"key":"a","text":"\\(e = \\dfrac{v^2}{127gR} - f\\)"},{"key":"b","text":"\\(e = \\dfrac{v^2}{127R} + f\\)"},{"key":"c","text":"\\(e = \\dfrac{v^2}{127R} - f\\)"},{"key":"d","text":"\\(e = \\dfrac{2v^2}{127gR} - f\\)"}],"answer":"c","explanation":"From \\(e + f = \\dfrac{v^2}{127R}\\), with \\(v\\) in km per h and \\(R\\) in m, \\[e = \\dfrac{v^2}{127R} - f\\]","marks":1,"source":{"kind":"past","set":17,"question":32,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q32 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-17-033","src":"PAST-17-033","text":"The central raised part of the road is called","options":[{"key":"a","text":"crown"},{"key":"b","text":"camber"},{"key":"c","text":"apex height"},{"key":"d","text":"super elevation"}],"answer":"a","explanation":"The crown is the highest point of the cross-section at the centre line. The camber is the cross slope falling from it to the edges.","marks":1,"source":{"kind":"past","set":17,"question":33,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q33 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-17-034","src":"PAST-17-034","text":"If the CBR ratio is 5%, the modulus of resilience is","options":[{"key":"a","text":"40 MPa"},{"key":"b","text":"50 MPa"},{"key":"c","text":"60 MPa"},{"key":"d","text":"70 MPa"}],"answer":"b","explanation":"For \\(\\text{CBR} \\le 5\\%\\), \\[M_R = 10 \\times \\text{CBR} = 50\\ \\text{MPa}\\]","marks":1,"source":{"kind":"past","set":17,"question":34,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q34 · 1 mark"},"topic":"ACiE0905"},{"id":"PAST-17-035","src":"PAST-17-035","text":"Bitumen grade 80/100 means","options":[{"key":"a","text":"its penetration value is 8 mm"},{"key":"b","text":"its penetration value is 10 mm"},{"key":"c","text":"its penetration value is 8 to 10 mm"},{"key":"d","text":"its penetration value is 8 to 10 cm"}],"answer":"c","explanation":"The needle penetration is 80–100 tenths of a mm, i.e. 8–10 mm, at 25°C.","marks":1,"source":{"kind":"past","set":17,"question":35,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q35 · 1 mark"},"topic":"ACiE0903"},{"id":"PAST-17-055","src":"PAST-17-055","text":"What is the length of the slender beam portion of the Benkelman beam?","options":[{"key":"a","text":"3.66 m"},{"key":"b","text":"2.44 m"},{"key":"c","text":"3.33 m"},{"key":"d","text":"2.22 m"}],"answer":"a","explanation":"The Benkelman beam is a slender beam 3.66 m long, pivoted 2.44 m from its probe end, and mounted on a datum frame with legs.","marks":1,"source":{"kind":"past","set":17,"question":55,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q55 · 1 mark"},"topic":"ACiE0905"},{"id":"PAST-17-059","src":"PAST-17-059","text":"An enoscope is used to determine","options":[{"key":"a","text":"spot speed"},{"key":"b","text":"average speed"},{"key":"c","text":"travel time"},{"key":"d","text":"none of these"}],"answer":"a","explanation":"The enoscope (mirror box) lets an observer time vehicles over a short known base, giving spot speeds.","marks":1,"source":{"kind":"past","set":17,"question":59,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q59 · 1 mark"},"topic":"ACiE0904"},{"id":"PAST-17-063","src":"PAST-17-063","text":"Find the CBR value at 2.5 mm penetration. The load sustained by the specimen at 2.5 mm penetration is 64.6 kg and the load sustained by standard aggregates at 2.5 mm penetration is 1370 kg.","options":[{"key":"a","text":"4.7%"},{"key":"b","text":"10.3%"},{"key":"c","text":"8.4%"},{"key":"d","text":"2.1%"}],"answer":"a","explanation":"The CBR is \\[\\dfrac{64.6}{1370} \\times 100 \\approx 4.7\\%\\]","marks":2,"source":{"kind":"past","set":17,"question":63,"marks":2,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q63 · 2 marks"},"topic":"ACiE0905"},{"id":"PAST-17-070","src":"PAST-17-070","text":"Assuming a coefficient of friction of 0.36 and a total reaction time of the driver of 2.5 sec, the stopping sight distance for a design speed of 65 kmph is","options":[{"key":"a","text":"55.25 m"},{"key":"b","text":"46.21 m"},{"key":"c","text":"4.62 m"},{"key":"d","text":"91.4 m"}],"answer":"d","explanation":"Here \\(v = 18.06\\) m per s, so \\[\\text{SSD} = vt + \\dfrac{v^2}{2gf}\\] \\[\\begin{aligned} &amp;= 45.1 + \\dfrac{326}{2 \\times 9.81 \\times 0.36} \\\\ &amp;\\approx 45.1 + 46.2 \\approx 91.4\\ \\text{m} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":17,"question":70,"marks":2,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q70 · 2 marks"},"topic":"ACiE0902"}]},{"name":"Project Planning, Design and Implementation","questions":[{"id":"PAST-17-005","src":"PAST-17-005","text":"Under which act is NEA founded?","options":[{"key":"a","text":"NEC Act 2055"},{"key":"b","text":"NEA Act 1962"},{"key":"c","text":"Social Service Act of the Government of Nepal"},{"key":"d","text":"All of the above"}],"answer":"c","explanation":"The Nepal Engineers' Association (founded 1962) is a registered professional society, which the key places under the government's social service (institution registration) legislation. It was not created by the NEC Act.","marks":1,"source":{"kind":"past","set":17,"question":5,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q5 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-17-006","src":"PAST-17-006","text":"The first amendment of the NEC Act was on","options":[{"key":"a","text":"2066/10/07"},{"key":"b","text":"2075/11/19"},{"key":"c","text":"2079/05/05"},{"key":"d","text":"2076/09/06"}],"answer":"c","explanation":"Per the source key, the first amendment of the NEC Act 2055 came into effect on 2079-05-05 BS.","marks":1,"source":{"kind":"past","set":17,"question":6,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q6 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-17-009","src":"PAST-17-009","text":"The qualification of the vice chairman of the Nepal Engineering Council is","options":[{"key":"a","text":"B.E + 15 years of experience"},{"key":"b","text":"M.E + 7 years of experience"},{"key":"c","text":"B.E + 10 years of experience"},{"key":"d","text":"B.E + 7 years of experience"}],"answer":"c","explanation":"The NEC Act requires the vice-chairperson to be an engineer with at least 10 years' experience after a bachelor's degree. The chairperson needs 15 years.","marks":1,"source":{"kind":"past","set":17,"question":9,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q9 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-17-010","src":"PAST-17-010","text":"NEC is","options":[{"key":"a","text":"Government body"},{"key":"b","text":"Autonomous body"},{"key":"c","text":"Independent body"},{"key":"d","text":"All of the above"}],"answer":"b","explanation":"NEC is an autonomous statutory body with perpetual succession, established by the NEC Act 2055.","marks":1,"source":{"kind":"past","set":17,"question":10,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q10 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-17-025","src":"PAST-17-025","text":"The number of members directly elected to the council from the Nepal Engineers' Association is","options":[{"key":"a","text":"2"},{"key":"b","text":"3"},{"key":"c","text":"4"},{"key":"d","text":"5"}],"answer":"d","explanation":"The NEC Act includes five engineers elected by the Nepal Engineers' Association as council members.","marks":1,"source":{"kind":"past","set":17,"question":25,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q25 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-17-026","src":"PAST-17-026","text":"The minimum qualification of a general engineer required to register in the Nepal Engineering Council is","options":[{"key":"a","text":"Bachelor's degree"},{"key":"b","text":"Diploma"},{"key":"c","text":"Master's degree"},{"key":"d","text":"Bachelor's degree along with two years of work experience"}],"answer":"a","explanation":"A bachelor's degree in engineering from a recognised institution (plus passing the licensing exam) qualifies for registration as a general engineer. Experience is not required at that level.","marks":1,"source":{"kind":"past","set":17,"question":26,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q26 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-17-027","src":"PAST-17-027","text":"The relation between total float, free float and interfering float is","options":[{"key":"a","text":"Interfering float = Total float + Free float"},{"key":"b","text":"Interfering float = Total float − Free float"},{"key":"c","text":"Interfering float = Total float − Free float − Duration"},{"key":"d","text":"Free float = Total float + Interfering float"}],"answer":"b","explanation":"Interfering float is the part of total float that, if used, delays succeeding activities: \\[\\text{IF} = \\text{TF} - \\text{FF}\\] which equals the head event slack.","marks":1,"source":{"kind":"past","set":17,"question":27,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q27 · 1 mark"},"topic":"AALL1003"},{"id":"PAST-17-028","src":"PAST-17-028","text":"What is the indication for the upward and downward direction of a cash flow diagram?","options":[{"key":"a","text":"Upward = positive cash flow, downward = negative cash flow"},{"key":"b","text":"Upward = inflows, downward = outflows"},{"key":"c","text":"Upward = income, downward = expenses"},{"key":"d","text":"All of the above"}],"answer":"d","explanation":"In a cash-flow diagram, upward arrows are receipts (inflows, income, positive flows) and downward arrows are disbursements (outflows, expenses). All three describe the same convention.","marks":1,"source":{"kind":"past","set":17,"question":28,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q28 · 1 mark"},"topic":"AALL1002"},{"id":"PAST-17-029","src":"PAST-17-029","text":"The Engineering Council Regulation started from","options":[{"key":"a","text":"2055"},{"key":"b","text":"2056"},{"key":"c","text":"2079"},{"key":"d","text":"2057"}],"answer":"d","explanation":"The Nepal Engineering Council Regulation was issued in 2057 BS under the NEC Act 2055.","marks":1,"source":{"kind":"past","set":17,"question":29,"marks":1,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q29 · 1 mark"},"topic":"AALL1006"},{"id":"PAST-17-071","src":"PAST-17-071","text":"The monthly interest rate will be …… if a nominal interest rate of 10% is accounted for with continuous compounding.","options":[{"key":"a","text":"1%"},{"key":"b","text":"0.84%"},{"key":"c","text":"1.2%"},{"key":"d","text":"2%"}],"answer":"b","explanation":"Continuous compounding gives an effective monthly rate of \\[e^{0.10{/}12} - 1 \\approx 0.84\\%\\]","marks":2,"source":{"kind":"past","set":17,"question":71,"marks":2,"date":"2080 Chaitra 29","shift":"1st shift","reference":"Past Paper Set 17, Q71 · 2 marks"},"topic":"AALL1002"}]}]};
